// swift-tools-version: 6.2
import PackageDescription

let package = Package(
    name: "RoverSwiftUI",
    // macOS 26 (Tahoe) — required for Liquid Glass (.glassEffect, GlassEffectContainer).
    platforms: [.macOS(.v26)],
    products: [
        .executable(name: "RoverApp", targets: ["RoverApp"]),
    ],
    dependencies: [
        .package(url: "https://github.com/Lakr233/libghostty-spm.git", branch: "main"),
    ],
    targets: [
        // ── C FFI module generated by UniFFI ────────────────────────────────
        .target(
            name: "rover_swiftFFI",
            path: "Sources/rover_swiftFFI",
            publicHeadersPath: ".",
            linkerSettings: [
                // build-swiftui.sh (or `swift package plugin rust-build`) copies
                // librover_swift.dylib into lib/ before every Swift build.
                .unsafeFlags(["-L", "lib"]),
                .linkedLibrary("rover_swift"),
            ]
        ),

        // ── Rust bindings + plugin protocol ─────────────────────────────────
        .target(
            name: "RoverCore",
            dependencies: ["rover_swiftFFI"],
            path: "Sources/RoverCore",
            swiftSettings: [.swiftLanguageMode(.v5)]
        ),

        // ── Native Swift plugins ─────────────────────────────────────────────
        .target(
            name: "RoverPlugins",
            dependencies: [
                "RoverCore",
                .product(name: "GhosttyTerminal", package: "libghostty-spm"),
            ],
            path: "Sources/RoverPlugins",
            swiftSettings: [.swiftLanguageMode(.v5)]
        ),

        // ── SwiftUI app (Entry / Panel / ViewModel / Views / Glass) ─────────
        .executableTarget(
            name: "RoverApp",
            dependencies: ["RoverCore", "RoverPlugins"],
            path: "Sources/RoverApp",
            swiftSettings: [.swiftLanguageMode(.v5)]
        ),

        // ── RustBuilder: thin executable invoked by the plugin ───────────────
        .executableTarget(
            name: "RustBuilder",
            path: "Sources/RustBuilder"
        ),

        // ── CommandPlugin: `swift package plugin rust-build` ─────────────────
        //    Run before every Swift build to compile the Rust cdylib and
        //    regenerate UniFFI bindings.
        //    Usage:
        //      swift package --package-path RoverSwiftUI \
        //        --allow-writing-to-package-directory \
        //        plugin rust-build
        .plugin(
            name: "RustBuildPlugin",
            capability: .command(
                intent: .custom(
                    verb: "rust-build",
                    description: "Compile rover_swift Rust crate and regenerate UniFFI Swift bindings"
                ),
                permissions: [
                    .writeToPackageDirectory(reason: "Writes librover_swift.dylib to lib/ and generated Swift bindings to Sources/")
                ]
            ),
            dependencies: ["RustBuilder"]
        ),

        .testTarget(
            name: "RoverSwiftUITests",
            dependencies: ["RoverCore", "RoverPlugins"],
            path: "Tests/RoverSwiftUITests",
            swiftSettings: [.swiftLanguageMode(.v5)]
        ),
    ]
)
